package com.andye.warmod.artillery.network;
import com.andye.warmod.WarMod;import net.minecraft.core.BlockPos;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.Identifier;
public record ServerboundArtilleryTargetPayload(int menuId, BlockPos position, double x, double y, double z) implements CustomPacketPayload { public static final Type<ServerboundArtilleryTargetPayload> TYPE=new Type<>(Identifier.fromNamespaceAndPath(WarMod.MOD_ID,"artillery_target")); public static final StreamCodec<RegistryFriendlyByteBuf,ServerboundArtilleryTargetPayload> STREAM_CODEC=StreamCodec.of((b,p)->{b.writeVarInt(p.menuId);b.writeBlockPos(p.position);b.writeDouble(p.x);b.writeDouble(p.y);b.writeDouble(p.z);},b->new ServerboundArtilleryTargetPayload(b.readVarInt(),b.readBlockPos(),b.readDouble(),b.readDouble(),b.readDouble()));@Override public Type<? extends CustomPacketPayload> type(){return TYPE;} }
